// 대한민국 공휴일 목록 (연도별 확장 가능)
const KR_HOLIDAYS = [
  // 2025
  '2025-01-01', '2025-01-28', '2025-01-29', '2025-01-30',
  '2025-03-01', '2025-05-05', '2025-05-06', '2025-06-06',
  '2025-08-15', '2025-10-03', '2025-10-05', '2025-10-06', '2025-10-07', '2025-10-09',
  '2025-12-25',
  // 2026
  '2026-01-01', '2026-02-16', '2026-02-17', '2026-02-18',
  '2026-03-01', '2026-05-05', '2026-06-06',
  '2026-08-17', '2026-09-24', '2026-09-25', '2026-09-26',
  '2026-10-03', '2026-10-09', '2026-12-25'
];

const now = new Date();
// KST = UTC+9
const kstOffset = 9 * 60 * 60 * 1000;
const kstNow = new Date(now.getTime() + kstOffset);

const pad = (n) => String(n).padStart(2, '0');
const todayStr = `${kstNow.getUTCFullYear()}-${pad(kstNow.getUTCMonth()+1)}-${pad(kstNow.getUTCDate())}`;
const dayOfWeek = kstNow.getUTCDay(); // 0=Sun, 1=Mon, ..., 5=Fri, 6=Sat

// 공휴일 또는 주말 체크
const isHoliday = KR_HOLIDAYS.includes(todayStr);
const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;

if (isHoliday || isWeekend) {
  return [{ json: { skip: true, reason: isHoliday ? '공휴일' : '주말', today: todayStr } }];
}

// Gmail 조회 시작 시간 계산
let since;
if (dayOfWeek === 1) {
  // 월요일: 지난 금요일 00:00 KST
  const friday = new Date(kstNow.getTime() - 3 * 24 * 60 * 60 * 1000);
  since = `${friday.getUTCFullYear()}-${pad(friday.getUTCMonth()+1)}-${pad(friday.getUTCDate())}T00:00:00+09:00`;
} else {
  // 화~금: 어제 00:00 KST
  const yesterday = new Date(kstNow.getTime() - 24 * 60 * 60 * 1000);
  since = `${yesterday.getUTCFullYear()}-${pad(yesterday.getUTCMonth()+1)}-${pad(yesterday.getUTCDate())}T00:00:00+09:00`;
}

const sinceUnix = Math.floor(new Date(since).getTime() / 1000);

return [{
  json: {
    skip: false,
    today: todayStr,
    dayOfWeek,
    isMonday: dayOfWeek === 1,
    since,
    sinceUnix,
    nowKST: kstNow.toISOString()
  }
}];

const emails = $input.all();
const dateInfo = $('공휴일/주말 체크 & 날짜 계산').item.json;

// 사내 발신자 목록
const INTERNAL_SENDERS = [
  '김영철', '정예진', '홍대영',
  'younghchul', 'yejin', 'daeyoung',
  'solardin.com'
];

const URGENT_KEYWORDS = ['긴급', '확인', '회신', '[긴급]', '[확인]', '[회신]'];

const EXCLUDE_PATTERNS = [
  /no.?reply/i, /noreply/i, /newsletter/i, /notification/i,
  /donotreply/i, /mailer.daemon/i, /auto.?reply/i, /자동발송/i,
  /시스템/i
];

const TARGET_EMAIL = 'han@solardin.com';

function isExcluded(from) {
  return EXCLUDE_PATTERNS.some(p => p.test(from));
}

function isInternalSender(from) {
  return INTERNAL_SENDERS.some(s => from.toLowerCase().includes(s.toLowerCase()));
}

function hasUrgentKeyword(subject) {
  return URGENT_KEYWORDS.some(k => subject.includes(k));
}

function isUnread(email) {
  const labels = email.json.labelIds || [];
  return labels.includes('UNREAD');
}

function isDirectRecipient(email) {
  const to = (email.json.headers?.to || email.json.payload?.headers?.find(h => h.name === 'To')?.value || '').toLowerCase();
  return to.includes(TARGET_EMAIL.toLowerCase());
}

function extractHeader(email, name) {
  const headers = email.json.payload?.headers || [];
  const h = headers.find(h => h.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : (email.json[name] || '');
}

function getDateDiff(dateStr) {
  const emailDate = new Date(dateStr);
  const now = new Date();
  const diffMs = now - emailDate;
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  return diffDays;
}

const processed = [];
const seenSubjects = new Map();

for (const email of emails) {
  const from = extractHeader(email, 'from');
  const subject = extractHeader(email, 'subject') || '(제목없음)';
  const date = extractHeader(email, 'date');
  const messageId = email.json.id;

  // 제외 필터
  if (isExcluded(from)) continue;

  const unread = isUnread(email);
  const internal = isInternalSender(from);
  const urgent = hasUrgentKeyword(subject);
  const directTo = isDirectRecipient(email);

  // 읽은 메일 필터: 사내 또는 긴급 키워드 없으면 제외
  if (!unread && !internal && !urgent) continue;

  // 반복 메일 중복 제거 (같은 제목 최신 1건만)
  const subjectKey = subject.replace(/^(Re:|Fwd:|FW:|답장:|전달:)\s*/gi, '').trim().toLowerCase();
  if (seenSubjects.has(subjectKey)) continue;
  seenSubjects.set(subjectKey, true);

  // 우선순위 결정
  let priority;
  if (directTo && (internal || internal)) {
    priority = 'P1';
  } else if (directTo || urgent) {
    priority = 'P2';
  } else if (internal) {
    priority = 'P3';
  } else {
    priority = 'P4';
  }

  // D-숫자 계산
  const daysAgo = getDateDiff(date);
  const dLabel = daysAgo === 0 ? 'D-0' : `D-${daysAgo}`;

  // snippet (미리보기)
  const snippet = email.json.snippet || '';

  processed.push({
    id: messageId,
    from,
    subject,
    date,
    dLabel,
    priority,
    unread,
    snippet,
    internal,
    urgent,
    directTo
  });
}

// 우선순위 정렬
const ORDER = { P1: 0, P2: 1, P3: 2, P4: 3 };
processed.sort((a, b) => ORDER[a.priority] - ORDER[b.priority]);

return [{ json: { emails: processed, dateInfo, total: processed.length } }];

const emailData = $('메일 필터링 & 우선순위 분류').item.json;
const calEvents = $('Google Calendar 5일 일정 조회').all();

const { emails, dateInfo } = emailData;

// 캘린더 이벤트 정리
const events = calEvents.map(e => ({
  title: e.json.summary || '(제목없음)',
  start: e.json.start?.dateTime || e.json.start?.date || '',
  id: e.json.id
}));

// P1/P2 subject 목록
const p1p2Subjects = emails
  .filter(e => e.priority === 'P1' || e.priority === 'P2')
  .map(e => e.subject.toLowerCase());

// 캘린더-메일 중복 여부 확인
const calWithFlag = events.map(ev => {
  const overlap = p1p2Subjects.some(s =>
    ev.title.toLowerCase().includes(s.substring(0, 10)) ||
    s.includes(ev.title.toLowerCase().substring(0, 10))
  );
  return { ...ev, overlapWithP1P2: overlap };
});

return [{ json: { emails, dateInfo, calEvents: calWithFlag } }];

